CREATE OR REPLACE FUNCTION public.audit_log_trigger_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  hdrs jsonb;
  v_before jsonb;
  v_after jsonb;
  v_ip inet;
  v_redact constant text[] := array
    ['cardcom_token', 'pin_hash', 'token_hash', 'confirm_token', 'unsubscribe_token', 'secret'];
begin
  begin
    hdrs := nullif(current_setting('request.headers', true), '')::jsonb;
  exception when others then
    hdrs := null;
  end;

  begin
    v_ip := nullif(trim(split_part(
      coalesce(hdrs->>'x-forwarded-for', hdrs->>'x-real-ip', ''), ',', 1)), '')::inet;
  exception when others then
    v_ip := null;
  end;

  if tg_op in ('UPDATE', 'DELETE') then
    v_before := to_jsonb(old) - v_redact;
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_after := to_jsonb(new) - v_redact;
  end if;

  insert into public.audit_log
    (actor_id, actor_role, action, entity_type, entity_id,
     changes, before, after, ip_address, user_agent, request_id)
  values (
    auth.uid(),
    public.current_user_role()::text,
    (case tg_op
       when 'INSERT' then 'created'
       when 'UPDATE' then 'updated'
       when 'DELETE' then 'deleted'
     end)::public.audit_action,
    tg_table_name::text,
    coalesce(v_after->>'id', v_before->>'id', ''),
    case tg_op
      when 'INSERT' then jsonb_build_object('new', v_after)
      when 'UPDATE' then jsonb_build_object('old', v_before, 'new', v_after)
      when 'DELETE' then jsonb_build_object('old', v_before)
    end,
    v_before,
    v_after,
    v_ip,
    left(hdrs->>'user-agent', 500),
    left(hdrs->>'x-request-id', 128)
  );
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_product_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW; -- service role / internal jobs
  END IF;

  IF NOT public.is_admin() THEN
    -- Non-admin (content_uploader by RLS): edits always require re-review.
    IF NEW.approval_status NOT IN ('draft'::public.product_approval_status,
                                   'pending'::public.product_approval_status) THEN
      NEW.approval_status := 'pending'::public.product_approval_status;
    END IF;
    IF TG_OP = 'UPDATE'
       AND OLD.approval_status = 'approved'::public.product_approval_status THEN
      NEW.approval_status := 'pending'::public.product_approval_status;
    END IF;
    NEW.approved_by := NULL;
    NEW.approved_at := NULL;
    IF NEW.approval_status = 'pending'::public.product_approval_status
       AND NEW.submitted_at IS NULL THEN
      NEW.submitted_at := now();
    END IF;
    -- Publishing is blocked until an admin approves.
    IF NEW.status = 'active'::public.product_status THEN
      RAISE EXCEPTION 'product requires admin approval before publishing'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    -- Admin path: activating a product implies approval.
    IF NEW.status = 'active'::public.product_status
       AND NEW.approval_status <> 'approved'::public.product_approval_status THEN
      NEW.approval_status := 'approved'::public.product_approval_status;
    END IF;
    IF NEW.approval_status = 'approved'::public.product_approval_status
       AND (TG_OP = 'INSERT'
            OR OLD.approval_status <> 'approved'::public.product_approval_status) THEN
      NEW.approved_by := auth.uid();
      NEW.approved_at := now();
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_search_index()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.search_index_outbox (product_id, op) VALUES (OLD.id, 'delete');
    RETURN OLD;
  END IF;
  IF NEW.deleted_at IS NOT NULL OR NEW.status <> 'active' THEN
    INSERT INTO public.search_index_outbox (product_id, op) VALUES (NEW.id, 'delete');
  ELSE
    INSERT INTO public.search_index_outbox (product_id, op) VALUES (NEW.id, 'upsert');
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_products_track_stock_initial()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.stock_quantity IS NULL THEN RETURN NEW; END IF;
  IF NEW.stock_initial IS NULL OR NEW.stock_quantity > COALESCE(OLD.stock_quantity, -1) THEN
    NEW.stock_initial := GREATEST(COALESCE(NEW.stock_initial, 0), NEW.stock_quantity);
  END IF;
  RETURN NEW;
END;
$function$
